import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"퀵 패널 설정","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/quick-panel.md","filePath":"ko-KR/user-guide/settings/quick-panel.md","lastUpdated":1787586465000}'),l={name:"ko-KR/user-guide/settings/quick-panel.md"};function n(a,t,i,g,d,c){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="퀵-패널-설정" tabindex="-1">퀵 패널 설정 <a class="header-anchor" href="#퀵-패널-설정" aria-label="Permalink to &quot;퀵 패널 설정&quot;">​</a></h1><p><strong>퀵 패널 (Quick Panel)</strong> 은 자주 사용하는 파일의 빠른 호출, 프로젝트 컨텍스트 관리 및 데스크톱 드래그 앤 드롭 파일 스테이징을 위해 설계된 플로팅 워크스페이스입니다. 단축키를 누르면 활성 창의 우측 하단에 자동 도킹되어 작업 중인 컨텍스트를 벗어나지 않고 파일을 빠르게 탐색하고 활용할 수 있습니다.</p><h2 id="_1-핵심-아키텍처-및-메인-스위치" tabindex="-1">1. 핵심 아키텍처 및 메인 스위치 <a class="header-anchor" href="#_1-핵심-아키텍처-및-메인-스위치" aria-label="Permalink to &quot;1. 핵심 아키텍처 및 메인 스위치&quot;">​</a></h2><ul><li><strong>퀵 패널 활성화</strong>: 전체 켜기/끄기 스위치로, 끄면 호출 단축키가 작동하지 않습니다.</li><li><strong>호출 단축키</strong>: 기본값 <strong><code>Ctrl+F2</code></strong>(<a href="./hotkeys-page.html"><strong>설정 → 단축키</strong></a>에서 변경 가능).</li><li><strong>스마트 도킹 및 크기 제한</strong>: 호스트 창의 너비 및 높이의 각 1/2 크기로 표시됩니다(시인성을 위해 최소 <code>280 × 200px</code>로 제한). Lertaro 자체 창이 활성 상태일 때는 중복 실행 방지를 위해 호출이 무시되며, 패널이 열려 있을 때 동일한 단축키를 누르면 닫힙니다.</li><li><strong>퀵 점프 연동</strong>: 패널이 열려 있는 동안 선택된 그룹의 디렉토리가 작업 경로로 자동 기록되어 파일 대화상자에서 <code>Ctrl+G</code>를 누르면 해당 경로로 즉시 이동합니다.</li></ul><h2 id="_2-워크스페이스-workspaces" tabindex="-1">2. 워크스페이스 (Workspaces) <a class="header-anchor" href="#_2-워크스페이스-workspaces" aria-label="Permalink to &quot;2. 워크스페이스 (Workspaces)&quot;">​</a></h2><p>프로젝트나 업무 단위로 폴더 그룹을 구성합니다.</p><ul><li><strong>워크스페이스 관리</strong>: 좌측 목록에서 <strong>새로 만들기</strong>, <strong>복제</strong>, <strong>삭제</strong>가 가능하며 드래그하여 탭 바의 표시 순서를 변경할 수 있습니다.</li><li><strong>속성</strong>: <ul><li><strong>이름</strong>: 탭에 표시되는 텍스트(비워둘 경우 언어 설정에 따른 기본 이름 적용).</li><li><strong>활성화 스위치</strong>: 탭 바 표시 여부 제어. 패널에서 탭의 <strong>×</strong> 버튼을 눌러 숨긴 경우 여기서 다시 켤 수 있습니다.</li></ul></li></ul><p>선택한 워크스페이스는 우측의 <strong>소스</strong> 및 <strong>애플리케이션</strong> 탭에서 구성합니다.</p><h2 id="_3-소스-설정-sources" tabindex="-1">3. 소스 설정 (Sources) <a class="header-anchor" href="#_3-소스-설정-sources" aria-label="Permalink to &quot;3. 소스 설정 (Sources)&quot;">​</a></h2><p>각 소스는 워크스페이스 내의 독립된 폴더 그룹을 나타냅니다.</p><ul><li><strong>폴더 추가</strong>: 대상 디렉토리를 선택합니다.</li><li><strong>표시 모드 (Display Mode)</strong>: <ul><li><strong>최근 변경된 파일</strong> —— 메모리 인덱스에서 최근 수정된 파일을 밀리초 단위로 조회(최신순).</li><li><strong>모든 파일, 최신순</strong> —— 수정일자 내림차순으로 전체 파일 표시.</li><li><strong>모든 파일, 이름순</strong> —— 고정 바로가기 바 형태로 활용.</li></ul></li><li><strong>하위 폴더 포함</strong>: 하위 디렉토리 파일을 재귀적으로 포함합니다.</li><li><strong>드롭된 파일 수락</strong>: 켜면 외부 파일, 폴더, 웹 이미지를 이 그룹으로 끌어다 놓아 복사할 수 있습니다(충돌 알림 및 실행 취소를 지원하는 Windows 표준 복사 사용).</li><li><strong>필터링 규칙</strong>: 와일드카드로 표시할 확장자 제한(예: <code>*.mp4;*.mkv</code> 또는 <code>*.pdf;*.docx</code>).</li><li><strong>최대 항목 수 및 시간 제한</strong>: 최대 표시 개수(0은 무제한) 및 N분 내 수정된 파일만 표시하도록 제한.</li><li><strong>상세 목록 vs 썸네일 타일</strong>: 그룹별로 목록 뷰 또는 썸네일 그리드 뷰를 선택 가능(타일은 원본 비율을 유지하며 균등 확장).</li></ul><h2 id="_4-플러그인-동적-탭-plugin-tabs" tabindex="-1">4. 플러그인 동적 탭 (Plugin Tabs) <a class="header-anchor" href="#_4-플러그인-동적-탭-plugin-tabs" aria-label="Permalink to &quot;4. 플러그인 동적 탭 (Plugin Tabs)&quot;">​</a></h2><p>플러그인이 제공하는 동적 목록을 퀵 패널에 배치할 수 있습니다. CoreExtensions에는 5개의 기본 탭이 포함되어 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">플러그인 탭</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>즐겨찾기</strong></td><td style="text-align:left;">별표로 등록된 항목(URL은 브라우저에서 실행).</td></tr><tr><td style="text-align:left;"><strong>기록</strong></td><td style="text-align:left;">Lertaro를 통해 실행된 최근 항목 및 프로그램.</td></tr><tr><td style="text-align:left;"><strong>Windows 기록</strong></td><td style="text-align:left;">Windows &quot;최근 사용한 파일&quot;을 실제 파일 경로로 해석.</td></tr><tr><td style="text-align:left;"><strong>최근 디렉토리</strong></td><td style="text-align:left;">탐색기나 대화상자에서 직전에 탐색했던 폴더 추적.</td></tr><tr><td style="text-align:left;"><strong>최근 파일</strong></td><td style="text-align:left;">설정된 폴더들의 최신 파일들을 인덱스를 통해 집계 표시.</td></tr></tbody></table><p>각 탭의 표시 여부와 목록/타일 뷰 형식을 개별 설정할 수 있습니다.</p><h2 id="_5-앱-연동-및-전용-블랙리스트" tabindex="-1">5. 앱 연동 및 전용 블랙리스트 <a class="header-anchor" href="#_5-앱-연동-및-전용-블랙리스트" aria-label="Permalink to &quot;5. 앱 연동 및 전용 블랙리스트&quot;">​</a></h2><ul><li><strong>애플리케이션 연동 (Applications)</strong>: 특정 프로세스 이름(예: <code>chrome.exe</code> 또는 <code>devenv.exe</code>)을 등록하면 해당 앱 위에서 퀵 패널을 호출했을 때 해당 워크스페이스가 자동 활성화됩니다.</li><li><strong>퀵 패널 전용 블랙리스트</strong>: 패널 표시를 차단할 프로세스를 등록합니다. 전역 블랙리스트에 <strong>추가</strong>되어 작동합니다.</li></ul><h2 id="_6-패널-조작-가이드" tabindex="-1">6. 패널 조작 가이드 <a class="header-anchor" href="#_6-패널-조작-가이드" aria-label="Permalink to &quot;6. 패널 조작 가이드&quot;">​</a></h2><ul><li><strong>실시간 퍼지 필터링</strong>: 우측 상단 검색창에서 fzf 퍼지 매칭 및 한어병음으로 작업 공간을 빠르게 필터링.</li><li><strong>키보드 탐색</strong>: 방향키로 그룹을 넘나들며 탐색하고 <code>Enter</code>로 실행.</li><li><strong>탭 전환</strong>: <code>Ctrl</code> + <code>1</code>–<code>9</code>로 각 탭 간 빠른 이동.</li><li><strong>QuickLook 미리보기 및 고정</strong>: <code>Alt+P</code>로 미리보기 패널 호출, <code>Ctrl+T</code>로 포커스를 잃어도 닫히지 않도록 고정.</li></ul>',19)])])}const p=o(l,[["render",n]]);export{h as __pageData,p as default};
